package edu.campus.recycle;
import org.springframework.http.HttpStatus; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import jakarta.annotation.PostConstruct; import java.util.*;
@RestController @RequestMapping("/api") @CrossOrigin
public class ApiController {
 private final JdbcTemplate db; public ApiController(JdbcTemplate db){this.db=db;} private long id(Object v){return Long.parseLong(String.valueOf(v));}
 @PostConstruct private void ensureReputationSchema(){try{db.execute("ALTER TABLE items MODIFY category_id BIGINT NULL");}catch(Exception ignored){}try{db.execute("ALTER TABLE items ADD COLUMN photo_url TEXT NULL");}catch(Exception ignored){}try{db.execute("ALTER TABLE items ADD COLUMN meeting_day VARCHAR(8) NULL");}catch(Exception ignored){}try{db.execute("ALTER TABLE items ADD COLUMN meeting_time VARCHAR(5) NULL");}catch(Exception ignored){}try{db.execute("ALTER TABLE items ADD COLUMN meeting_location VARCHAR(30) NULL");}catch(Exception ignored){}try{db.execute("ALTER TABLE trade_orders ADD COLUMN meeting_day VARCHAR(8) NULL");}catch(Exception ignored){}try{db.execute("ALTER TABLE trade_orders ADD COLUMN meeting_time VARCHAR(5) NULL");}catch(Exception ignored){}try{db.execute("ALTER TABLE trade_orders ADD COLUMN meeting_location VARCHAR(30) NULL");}catch(Exception ignored){}try{db.execute("ALTER TABLE users ADD COLUMN reputation_score INT NOT NULL DEFAULT 100");}catch(Exception ignored){}try{db.execute("ALTER TABLE users ADD COLUMN reputation_bonus_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP");}catch(Exception ignored){}db.execute("CREATE TABLE IF NOT EXISTS reputation_records (id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,change_points INT NOT NULL,reason VARCHAR(200) NOT NULL,source_id BIGINT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_reputation_user FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB");db.execute("CREATE TABLE IF NOT EXISTS trade_feedback (id BIGINT PRIMARY KEY AUTO_INCREMENT,trade_id BIGINT NOT NULL UNIQUE,buyer_id BIGINT NOT NULL,rating TINYINT NOT NULL,comment VARCHAR(255),created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_feedback_trade FOREIGN KEY(trade_id) REFERENCES trade_orders(id),CONSTRAINT fk_feedback_buyer FOREIGN KEY(buyer_id) REFERENCES users(id)) ENGINE=InnoDB");}
 private int reputation(long uid){
  // Read DATETIME through JDBC's typed accessor; getObject may return LocalDateTime.
  return db.queryForObject("SELECT reputation_score,reputation_bonus_at FROM users WHERE id=? AND status='ACTIVE'",(rs,rowNum)->{
   int score=rs.getInt("reputation_score");
   int days=(int)((System.currentTimeMillis()-rs.getTimestamp("reputation_bonus_at").getTime())/86400000L);
   int bonus=days/10;
   if(bonus>0){db.update("UPDATE users SET reputation_score=reputation_score+?,reputation_bonus_at=DATE_ADD(reputation_bonus_at,INTERVAL ? DAY) WHERE id=?",bonus,bonus*10,uid);score+=bonus;}
   return score;
  },uid);
 }
 private void canOperate(long uid){if(reputation(uid)<90)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"信誉积分低于90分，暂时不能进行此操作");}
 private void changeReputation(long uid,int delta,String reason,long source){reputation(uid);db.update("UPDATE users SET reputation_score=reputation_score+? WHERE id=?",delta,uid);db.update("INSERT INTO reputation_records(user_id,change_points,reason,source_id) VALUES(?,?,?,?)",uid,delta,reason,source);}
 private void admin(long uid){Integer n=db.queryForObject("SELECT COUNT(*) FROM users WHERE id=? AND role='ADMIN' AND status='ACTIVE'",Integer.class,uid);if(n==null||n==0)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"需要管理员权限");}
 private void withdrawalPermission(long uid,boolean owner){Integer n=db.queryForObject("SELECT COUNT(*) FROM users WHERE id=? AND status='ACTIVE'",Integer.class,uid);if(n==null||n==0)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"用户不可用");if(!owner)admin(uid);}
 @PutMapping("/trades/{tradeId}/withdraw") @Transactional
 public Map<String,Object> withdrawTrade(@PathVariable long tradeId,@RequestBody Map<String,Object>b){
  long uid=id(b.get("operatorId"));Map<String,Object>t=db.queryForMap("SELECT item_id,buyer_id,seller_id,status FROM trade_orders WHERE id=? FOR UPDATE",tradeId);
  if(uid!=id(t.get("buyer_id"))&&uid!=id(t.get("seller_id")))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"只有交易双方可以撤回订单");
  if(!Set.of("PENDING","APPLIED","PROCESSING").contains(String.valueOf(t.get("status"))))throw new ResponseStatusException(HttpStatus.CONFLICT,"该订单已结束，不能撤回");
  db.update("UPDATE trade_orders SET status='CANCELLED' WHERE id=?",tradeId);
  db.update("UPDATE items SET status='APPROVED' WHERE id=? AND status IN ('APPLIED','PROCESSING') AND NOT EXISTS (SELECT 1 FROM trade_orders WHERE item_id=? AND status IN ('APPLIED','PROCESSING','COMPLETED'))",t.get("item_id"),t.get("item_id"));
  return Map.of("message","订单已撤回");
 }
 @PutMapping("/recycling-orders/{orderId}/withdraw") @Transactional
 public Map<String,Object> withdrawRecycle(@PathVariable long orderId,@RequestBody Map<String,Object>b){
  long uid=id(b.get("operatorId"));Map<String,Object>o=db.queryForMap("SELECT item_id,applicant_id,status FROM recycling_orders WHERE id=? FOR UPDATE",orderId);
  withdrawalPermission(uid,uid==id(o.get("applicant_id")));
  if(!Set.of("APPLIED","APPOINTED","PROCESSING").contains(String.valueOf(o.get("status"))))throw new ResponseStatusException(HttpStatus.CONFLICT,"该预约已结束，不能撤回");
  db.update("UPDATE recycling_orders SET status='CANCELLED' WHERE id=?",orderId);
  db.update("UPDATE items SET status='APPROVED' WHERE id=? AND status IN ('APPLIED','PROCESSING')",o.get("item_id"));
  return Map.of("message","回收预约已撤回");
 }
 @PostMapping("/auth/register") public Map<String,Object> register(@RequestBody Map<String,Object>b){String username=String.valueOf(b.getOrDefault("username","")),password=String.valueOf(b.getOrDefault("password","")),realName=String.valueOf(b.getOrDefault("realName","")),phone=Objects.toString(b.get("phone"),"").trim();if(!username.matches("[A-Za-z0-9_]{3,32}"))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"用户名为3-32位字母、数字或下划线");if(password.length()<6||password.length()>32)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"密码长度为6-32位");if(realName.isBlank()||realName.length()>50)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"请输入有效的真实姓名");if(!phone.isBlank()&&!phone.matches("1[3-9]\\d{9}"))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"手机号格式不正确");db.update("INSERT INTO users(username,password_hash,real_name,phone) VALUES(?,?,?,?)",username,password,realName,phone.isBlank()?null:phone);return Map.of("message","注册成功");}
 @PostMapping("/auth/login") public Map<String,Object> login(@RequestBody Map<String,Object>b){List<Map<String,Object>>r=db.queryForList("SELECT id,username,real_name,phone,role,total_points,reputation_score FROM users WHERE username=? AND password_hash=? AND status='ACTIVE'",b.get("username"),b.get("password"));if(r.isEmpty())throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"账号或密码错误");Map<String,Object>u=r.get(0);u.put("reputation_score",reputation(id(u.get("id"))));return u;}
 @GetMapping("/users/{id}") public Map<String,Object> user(@PathVariable long id){return db.queryForMap("SELECT id,username,real_name,phone,role,total_points,created_at FROM users WHERE id=?",id);}
 @GetMapping("/items") public Map<String,Object> items(@RequestParam(required=false)String keyword,@RequestParam(required=false)Long categoryId,@RequestParam(required=false)String processType,@RequestParam(required=false)String status,@RequestParam(required=false)Long ownerId,@RequestParam(defaultValue="false")boolean ownerOnly,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="10")int size){StringBuilder w=new StringBuilder(" WHERE 1=1 ");List<Object>p=new ArrayList<>();if(ownerOnly&&ownerId!=null){w.append(" AND i.owner_id=?");p.add(ownerId);}else if(ownerId!=null){w.append(" AND (i.status='APPROVED' OR i.owner_id=?)");p.add(ownerId);}else{w.append(" AND i.status='APPROVED'");}if(keyword!=null&&!keyword.isBlank()){w.append(" AND i.name LIKE ?");p.add("%"+keyword+"%");}if(categoryId!=null){w.append(" AND i.category_id=?");p.add(categoryId);}if(processType!=null&&!processType.isBlank()){w.append(" AND i.process_type=?");p.add(processType);}if(status!=null&&!status.isBlank()){w.append(" AND i.status=?");p.add(status);}int s=Math.min(Math.max(size,1),50);List<Object>q=new ArrayList<>(p);q.add(s);q.add(Math.max(page,0)*s);Map<String,Object>o=new HashMap<>();o.put("records",db.queryForList("SELECT i.*,c.name category_name,u.real_name owner_name FROM items i LEFT JOIN categories c ON c.id=i.category_id JOIN users u ON u.id=i.owner_id"+w+" ORDER BY i.published_at DESC LIMIT ? OFFSET ?",q.toArray()));o.put("total",db.queryForObject("SELECT COUNT(*) FROM items i"+w,p.toArray(),Long.class));return o;}
 @GetMapping("/admin/items/review") public List<Map<String,Object>> reviewItems(@RequestParam long operatorId){admin(operatorId);return db.queryForList("SELECT i.*,c.name category_name,u.real_name owner_name FROM items i LEFT JOIN categories c ON c.id=i.category_id JOIN users u ON u.id=i.owner_id WHERE i.status='PENDING_REVIEW' ORDER BY i.published_at ASC");}
 @PutMapping("/admin/items/{itemId}/review") @Transactional public Map<String,Object> reviewItem(@PathVariable long itemId,@RequestBody Map<String,Object>b){long uid=id(b.get("operatorId"));admin(uid);boolean approved=Boolean.parseBoolean(String.valueOf(b.getOrDefault("approved",false)));String reason=String.valueOf(b.getOrDefault("reason",""));if(!approved&&(reason.isBlank()||reason.length()>255))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"请填写不超过255字的驳回原因");Map<String,Object>item=db.queryForMap("SELECT status,owner_id FROM items WHERE id=? FOR UPDATE",itemId);if(!"PENDING_REVIEW".equals(String.valueOf(item.get("status"))))throw new ResponseStatusException(HttpStatus.CONFLICT,"该物品不在待审核状态");db.update("UPDATE items SET status=?,review_reason=?,reviewed_by=?,reviewed_at=NOW() WHERE id=?",approved?"APPROVED":"REJECTED",reason.isBlank()?null:reason,uid,itemId);if(!approved)changeReputation(id(item.get("owner_id")),-5,"物品审核被管理员拒绝",itemId);return Map.of("message",approved?"审核通过，物品已上架":"审核未通过，信誉积分-5");}
 @GetMapping("/categories")public List<Map<String,Object>> categories(){return db.queryForList("SELECT * FROM categories ORDER BY id");}
 @GetMapping("/recycling-stations")public List<Map<String,Object>> stations(){return db.queryForList("SELECT * FROM recycling_stations WHERE status='OPEN' ORDER BY id");}
 @PostMapping("/items")public Map<String,Object> create(@RequestBody Map<String,Object>b){long ownerId=id(b.get("ownerId"));canOperate(ownerId);String name=String.valueOf(b.getOrDefault("name",""));String processType=String.valueOf(b.getOrDefault("processType",""));double price=Double.parseDouble(String.valueOf(b.getOrDefault("currentPrice",0)));if(!Double.isFinite(price))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"价格不合法");if(name.isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"物品名称不能为空");if(!Set.of("SELL","GIVE","RECYCLE").contains(processType))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"处理方式不合法");TradingMeeting.validate(processType,b);if(price<0||("SELL".equals(processType)&&price<=0)||(!"SELL".equals(processType)&&price!=0))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"出售价格必须大于0，赠送和回收价格必须为0");db.update("INSERT INTO items(owner_id,category_id,name,description,photo_url,condition_level,original_price,current_price,estimated_recycle_price,process_type,meeting_day,meeting_time,meeting_location,status) VALUES(?,NULL,?,?,?, ?,?,?,?, ?,?,?,?,'PENDING_REVIEW')",ownerId,name,b.get("description"),b.get("photoUrl"),b.getOrDefault("conditionLevel","GOOD"),b.getOrDefault("originalPrice",0),price,b.getOrDefault("estimatedRecyclePrice",0),processType,b.get("meetingDay"),b.get("meetingTime"),b.get("meetingLocation"));return Map.of("message","发布成功，等待管理员审核");}
 @PutMapping("/items/{itemId}")public Map<String,Object> update(@PathVariable long itemId,@RequestBody Map<String,Object>b){long uid=id(b.get("ownerId"));Integer n=db.queryForObject("SELECT COUNT(*) FROM items WHERE id=? AND owner_id=? AND status IN ('PENDING_REVIEW','REJECTED','APPROVED')",Integer.class,itemId,uid);if(n==null||n==0)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"无权修改或物品已完成");TradingMeeting.validate(db.queryForObject("SELECT process_type FROM items WHERE id=?",String.class,itemId),b);db.update("UPDATE items SET name=?,description=?,current_price=?,estimated_recycle_price=?,category_id=?,meeting_day=?,meeting_time=?,meeting_location=?,status='PENDING_REVIEW',review_reason=NULL,reviewed_by=NULL,reviewed_at=NULL WHERE id=?",b.get("name"),b.get("description"),b.get("currentPrice"),b.get("estimatedRecyclePrice"),b.get("categoryId"),b.get("meetingDay"),b.get("meetingTime"),b.get("meetingLocation"),itemId);return Map.of("message","修改成功，请等待重新审核");}
 @DeleteMapping("/items/{itemId}")public Map<String,Object> offline(@PathVariable long itemId,@RequestParam long ownerId){if(db.update("UPDATE items SET status='OFFLINE' WHERE id=? AND owner_id=? AND status IN ('PENDING_REVIEW','REJECTED','APPROVED','PENDING')",itemId,ownerId)==0)throw new ResponseStatusException(HttpStatus.CONFLICT,"物品当前不能下架");return Map.of("message","已下架");}
 @PostMapping("/trades")@Transactional public Map<String,Object> trade(@RequestBody Map<String,Object>b){canOperate(id(b.get("buyerId")));Map<String,Object>i=db.queryForMap("SELECT owner_id,process_type,current_price,status,meeting_day,meeting_time,meeting_location FROM items WHERE id=? FOR UPDATE",b.get("itemId"));if(!Set.of("SELL","GIVE").contains(String.valueOf(i.get("process_type")))||!String.valueOf(i.get("status")).equals("APPROVED"))throw new ResponseStatusException(HttpStatus.CONFLICT,"物品尚未审核通过或不可申请");if(id(i.get("owner_id"))==id(b.get("buyerId")))throw new ResponseStatusException(HttpStatus.CONFLICT,"不能申请自己的物品");db.update("INSERT INTO trade_orders(item_id,buyer_id,seller_id,process_type,amount,meeting_day,meeting_time,meeting_location) VALUES(?,?,?,?,?,?,?,?)",b.get("itemId"),b.get("buyerId"),i.get("owner_id"),i.get("process_type"),"GIVE".equals(String.valueOf(i.get("process_type")))?0:i.get("current_price"),i.get("meeting_day"),i.get("meeting_time"),i.get("meeting_location"));db.update("UPDATE items SET status='APPLIED' WHERE id=?",b.get("itemId"));return Map.of("message","申请已提交");}
 @GetMapping("/trades")public List<Map<String,Object>> trades(@RequestParam long userId,@RequestParam(defaultValue="false")boolean admin){if(admin)admin(userId);String sql="SELECT t.*,i.name item_name,b.real_name buyer_name,s.real_name seller_name FROM trade_orders t JOIN items i ON i.id=t.item_id JOIN users b ON b.id=t.buyer_id JOIN users s ON s.id=t.seller_id"+(admin?"":" WHERE t.buyer_id=? OR t.seller_id=?")+" ORDER BY t.applied_at DESC";return db.queryForList(sql,admin?new Object[]{}:new Object[]{userId,userId});}
 @PutMapping("/trades/{tradeId}/status")@Transactional public Map<String,Object> tradeStatus(@PathVariable long tradeId,@RequestBody Map<String,Object>b){long uid=id(b.get("operatorId"));String next=String.valueOf(b.get("status"));if(!Set.of("PROCESSING","COMPLETED").contains(next))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"非法状态");Map<String,Object>t=db.queryForMap("SELECT item_id,buyer_id,seller_id,status FROM trade_orders WHERE id=? FOR UPDATE",tradeId);if(uid!=id(t.get("buyer_id"))&&uid!=id(t.get("seller_id")))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"只有交易双方可以处理订单");String cur=String.valueOf(t.get("status"));if(!(cur.equals("APPLIED")&&next.equals("PROCESSING")&&uid==id(t.get("seller_id")))&&!(cur.equals("PROCESSING")&&next.equals("COMPLETED")&&uid==id(t.get("buyer_id"))))throw new ResponseStatusException(HttpStatus.CONFLICT,"非法状态转换或当前用户无权操作");db.update("UPDATE trade_orders SET status=?,completed_at=IF(?='COMPLETED',NOW(),completed_at) WHERE id=?",next,next,tradeId);if(next.equals("PROCESSING"))db.update("UPDATE items SET status='PROCESSING' WHERE id=?",t.get("item_id"));if(next.equals("COMPLETED"))db.update("UPDATE items SET status='COMPLETED',completed_at=NOW() WHERE id=?",t.get("item_id"));return Map.of("message",next.equals("PROCESSING")?"卖家已确认，等待买家完成交易":"交易已完成");}
 @PostMapping("/recycling-orders")@Transactional public Map<String,Object> recycle(@RequestBody Map<String,Object>b){
  long uid=id(b.get("applicantId"));canOperate(uid);
  Map<String,Object> item=db.queryForMap("SELECT owner_id,process_type,status FROM items WHERE id=? FOR UPDATE",b.get("itemId"));
  if(uid!=id(item.get("owner_id"))||!"RECYCLE".equals(item.get("process_type"))||!"APPROVED".equals(item.get("status")))throw new ResponseStatusException(HttpStatus.CONFLICT,"只能预约自己已审核通过的回收物品");
  Integer open=db.queryForObject("SELECT COUNT(*) FROM recycling_stations WHERE id=? AND status='OPEN'",Integer.class,b.get("stationId"));
  if(open==0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"请选择有效且开放的回收点");
  List<Map<String,Object>> previous=db.queryForList("SELECT id,status FROM recycling_orders WHERE item_id=?",b.get("itemId"));
  if(!previous.isEmpty()){
   if(!"CANCELLED".equals(previous.get(0).get("status")))throw new ResponseStatusException(HttpStatus.CONFLICT,"该物品已有回收预约");
   db.update("UPDATE recycling_orders SET status='APPLIED',station_id=?,appointment_at=?,applied_at=NOW(),completed_at=NULL WHERE id=?",b.get("stationId"),b.get("appointmentAt"),previous.get(0).get("id"));
  }else db.update("INSERT INTO recycling_orders(item_id,applicant_id,station_id,appointment_at) VALUES(?,?,?,?)",b.get("itemId"),uid,b.get("stationId"),b.get("appointmentAt"));
  db.update("UPDATE items SET status='APPLIED' WHERE id=?",b.get("itemId"));return Map.of("message","回收申请已提交");
 }
 @GetMapping("/recycling-orders")public List<Map<String,Object>> recycling(@RequestParam long userId,@RequestParam(defaultValue="false")boolean admin){if(admin)admin(userId);String sql="SELECT ro.*,i.name item_name,s.name station_name FROM recycling_orders ro JOIN items i ON i.id=ro.item_id JOIN recycling_stations s ON s.id=ro.station_id"+(admin?"":" WHERE ro.applicant_id=?")+" ORDER BY ro.applied_at DESC";return db.queryForList(sql,admin?new Object[]{}:new Object[]{userId});}
 @PutMapping("/recycling-orders/{orderId}/status")@Transactional public Map<String,Object> recycleStatus(@PathVariable long orderId,@RequestBody Map<String,Object>b){
  admin(id(b.get("operatorId")));String next=String.valueOf(b.get("status"));
  Map<String,Object> order=db.queryForMap("SELECT item_id,status FROM recycling_orders WHERE id=? FOR UPDATE",orderId);String current=String.valueOf(order.get("status"));
  if(next.equals("CANCELLED")){if(!Set.of("APPLIED","APPOINTED","PROCESSING").contains(current))throw new ResponseStatusException(HttpStatus.CONFLICT,"已结束的预约不能取消");}
  else if(!(current.equals("APPLIED")&&next.equals("APPOINTED"))&&!(current.equals("APPOINTED")&&next.equals("PROCESSING")))throw new ResponseStatusException(HttpStatus.CONFLICT,"非法状态转换");
  db.update("UPDATE recycling_orders SET status=? WHERE id=?",next,orderId);
  if(next.equals("CANCELLED"))db.update("UPDATE items SET status='APPROVED' WHERE id=?",order.get("item_id"));
  if(next.equals("PROCESSING"))db.update("UPDATE items SET status='PROCESSING' WHERE id=?",order.get("item_id"));
  return Map.of("message","状态已更新");
 }
 @PostMapping("/recycling-orders/{orderId}/complete")@Transactional public Map<String,Object> complete(@PathVariable long orderId,@RequestBody Map<String,Object>b){admin(id(b.get("operatorId")));Map<String,Object>o=db.queryForMap("SELECT ro.applicant_id,ro.item_id,i.category_id,COALESCE(c.point_factor,1.00) point_factor FROM recycling_orders ro JOIN items i ON i.id=ro.item_id LEFT JOIN categories c ON c.id=i.category_id WHERE ro.id=? AND ro.status='PROCESSING' FOR UPDATE",orderId);double w=Double.parseDouble(String.valueOf(b.get("weightKg")));if(!Double.isFinite(w)||w<=0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"重量必须大于0");int points=(int)Math.round(w*Double.parseDouble(String.valueOf(o.get("point_factor"))));db.update("UPDATE recycling_orders SET status='COMPLETED',completed_at=NOW() WHERE id=?",orderId);db.update("UPDATE items SET status='COMPLETED',completed_at=NOW() WHERE id=?",o.get("item_id"));db.update("INSERT INTO recycling_records(recycling_order_id,category_id,weight_kg,recycle_amount,contribution_points) VALUES(?,?,?,?,?)",orderId,o.get("category_id"),w,b.getOrDefault("recycleAmount",0),points);Long rid=db.queryForObject("SELECT id FROM recycling_records WHERE recycling_order_id=?",Long.class,orderId);if(points>0)db.update("INSERT INTO eco_point_records(user_id,recycling_record_id,change_points,reason) VALUES(?,?,?,?)",o.get("applicant_id"),rid,points,"完成物品回收");db.update("UPDATE users SET total_points=total_points+? WHERE id=?",points,o.get("applicant_id"));return Map.of("points",points,"message","回收完成，积分已入账");}
 @PostMapping("/trades/{tradeId}/feedback") @Transactional public Map<String,Object> feedback(@PathVariable long tradeId,@RequestBody Map<String,Object>b){long uid=id(b.get("buyerId"));int rating=Integer.parseInt(String.valueOf(b.get("rating")));if(rating<1||rating>5)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"评分必须为1-5分");Map<String,Object>t=db.queryForMap("SELECT buyer_id,seller_id,status FROM trade_orders WHERE id=?",tradeId);if(uid!=id(t.get("buyer_id"))||!"COMPLETED".equals(String.valueOf(t.get("status"))))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"只有完成订单的买家可以评价");db.update("INSERT INTO trade_feedback(trade_id,buyer_id,rating,comment) VALUES(?,?,?,?)",tradeId,uid,rating,b.getOrDefault("comment",""));int delta=rating>=4?2:rating<=2?-2:0;if(delta!=0)changeReputation(id(t.get("seller_id")),delta,"买家反馈评分"+rating+"分",tradeId);return Map.of("message","评价已提交");}
 @GetMapping("/points")public Map<String,Object> points(@RequestParam long userId){Map<String,Object>r=new HashMap<>();r.put("total",db.queryForObject("SELECT total_points FROM users WHERE id=?",Integer.class,userId));r.put("reputation",reputation(userId));r.put("reputationRecords",db.queryForList("SELECT * FROM reputation_records WHERE user_id=? ORDER BY created_at DESC",userId));r.put("records",db.queryForList("SELECT * FROM eco_point_records WHERE user_id=? ORDER BY created_at DESC",userId));return r;}
 @GetMapping("/stats/overview")public Map<String,Object> stats(){Map<String,Object>r=new HashMap<>();r.put("monthly",db.queryForList("SELECT * FROM v_monthly_item_stats ORDER BY month"));r.put("categories",db.queryForList("SELECT * FROM v_category_stats"));r.put("methods",db.queryForList("SELECT process_type,COUNT(*) quantity FROM items GROUP BY process_type"));r.put("stations",db.queryForList("SELECT * FROM v_station_recycle_stats ORDER BY total_weight DESC"));r.put("ranking",db.queryForList("SELECT u.real_name,SUM(e.change_points) total_points FROM users u JOIN eco_point_records e ON e.user_id=u.id GROUP BY u.id,u.real_name ORDER BY total_points DESC"));return r;}
 @GetMapping("/admin/users")public List<Map<String,Object>> users(@RequestParam long operatorId){admin(operatorId);return db.queryForList("SELECT id,username,real_name,phone,role,status,total_points,created_at FROM users ORDER BY id");}
 @GetMapping("/admin/recycling-records")public List<Map<String,Object>> records(@RequestParam long operatorId){admin(operatorId);return db.queryForList("SELECT rr.*,i.name item_name,s.name station_name,u.real_name applicant_name FROM recycling_records rr JOIN recycling_orders ro ON ro.id=rr.recycling_order_id JOIN items i ON i.id=ro.item_id JOIN recycling_stations s ON s.id=ro.station_id JOIN users u ON u.id=ro.applicant_id ORDER BY rr.recycled_at DESC");}
}
